\',\'models/self/convnextv2_modified.py\',\'models/utils.py\']:\n    original=source/name;assert hashlib.sha256(original.read_bytes()).digest()==hashlib.sha256((repo/name).read_bytes()).digest(),name\n    dest=target/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(original,dest);manifest[name]=hashlib.sha256(dest.read_bytes()).hexdigest()\nshutil.copy2(repo/\'infer_topk.py\',target/\'infer_topk.py\');manifest[\'infer_topk.py\']=hashlib.sha256((target/\'infer_topk.py\').read_bytes()).hexdigest()\n(out/\'minimal_runtime_manifest.json\').write_text(json.dumps({\'source\':str(source),\'files\':manifest,\'training_entrypoint_present\':False},indent=2)+\'\\n\')\nprint(\'Prepared 4-file minimum inference runtime\')\nPY\npython "$OUTPUT_DIR/minimal_runtime/infer_topk.py" --data "$DATA_PATH/test" --checkpoint "$CKPT" --class-labels "$CLASS_LABELS" --output "$OUTPUT_DIR/topk" --k 3 --conf 0.7 --batch-size 64 --num-workers 10 --seed 0 --amp true > "$OUTPUT_DIR/topk/stdout.jsonl" 2> "$OUTPUT_DIR/topk/stderr.log"\nsample=$(find "$DATA_PATH/test" -type f -name \'*.png\' | sort | head -n 1 || true)\npython "$OUTPUT_DIR/minimal_runtime/infer_topk.py" --data "$sample" --checkpoint "$CKPT" --class-labels "$CLASS_LABELS" --output "$OUTPUT_DIR/boundary_smoke" --k 7 --conf 0 --device cpu --amp false --batch-size 1 --num-workers 0 > "$OUTPUT_DIR/boundary_smoke/stdout.jsonl" 2> "$OUTPUT_DIR/boundary_smoke/stderr.log"\npython - <<\'PY\'\nimport csv,json,os\nfrom pathlib import Path\nroot=Path(os.environ[\'OUTPUT_DIR\'])\nwith (root/\'reference/eval_predictions.csv\').open() as f:reference={r[\'path\']:r for r in csv.DictReader(f)}\nactual=[json.loads(line) for line in (root/\'topk/all_predictions.jsonl\').read_text().splitlines()]\nassert len(reference)==len(actual)==2214 and set(reference)=={r[\'path\'] for r in actual}\nassert all(reference[r[\'path\']][\'pred_label\']==r[\'pred_label\'] and float(reference[r[\'path\']][\'pred_prob\'])==r[\'top1_conf\'] for r in actual)\nsmoke=json.loads((root/\'boundary_smoke/summary.json\').read_text());assert smoke[\'k\']==7 and smoke[\'conf\']==0 and smoke[\'samples\']==1 and smoke[\'low_confidence_samples\']==0\nprint(\'PASS: identical predictions and confidences on all 2214 images; k=7/conf=0 CPU single-image smoke passed\')\nPY' 
